    /// Load all typedef schemas keyed by table name.
    fn load_all_typedefs(
        &self,
        repo: &dyn DoogatSource,
    ) -> std::collections::HashMap<String, TableSchema>;
}

/// Optional secondary NoSQL mirror (best-effort dual write).
