/// `offset` enable pagination; transports that do not expose pagination
/// may leave them `None` to use service defaults.
#[derive(Debug, Clone)]
pub struct SearchCommand {
    pub query: String,
    pub limit: Option<usize>,
    pub offset: Option<usize>,
}

