use std::sync::{Arc, Mutex};

use async_graphql::dynamic::ResolverContext;
use async_graphql::extensions::{
    Extension, ExtensionContext, ExtensionFactory, NextPrepareRequest, NextRequest,
};
use async_graphql::{Request, Response, ServerResult};
use async_trait::async_trait;
use ddb_core::app_contract::AppWarning;

#[derive(Debug, Clone, PartialEq)]
pub struct WarningEntry {
    pub code: &'static str,
    pub message: String,
}

#[derive(Debug, Default)]
pub struct WarningCollector {
    warnings: Mutex<Vec<WarningEntry>>,
}

impl WarningCollector {
    pub fn push_warning(&self, code: &'static str, message: String) {
        self.warnings
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .push(WarningEntry { code, message });
    }

    pub fn drain_warnings(&self) -> Vec<WarningEntry> {
        self.warnings
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .drain(..)
            .collect()
    }
}

pub fn forward_warnings(ctx: &ResolverContext<'_>, warnings: &[AppWarning]) {
    match ctx.data::<Arc<WarningCollector>>() {
        Ok(collector) => {
            for w in warnings {
                collector.push_warning(w.code, w.message.clone());
            }
        }
        Err(_) => {
            // build_schema installs WarningExtensionFactory unconditionally, so
            // a missing collector means the schema was assembled without it —
            // a configuration bug that would silently drop warnings. Surface
            // it loudly so it's debuggable instead of swallowed.
            tracing::warn!(
                target: "ddb_server::warnings",
                "WarningCollector missing from request data; {} warning(s) dropped",
                warnings.len(),
            );
        }
    }
}

pub struct WarningExtensionFactory;

impl ExtensionFactory for WarningExtensionFactory {
    fn create(&self) -> Arc<dyn Extension> {
        Arc::new(WarningExtension {
            collector: Arc::new(WarningCollector::default()),
        })
    }
}

pub struct WarningExtension {
    collector: Arc<WarningCollector>,
}

#[async_trait]
impl Extension for WarningExtension {
    async fn prepare_request(
        &self,
        ctx: &ExtensionContext<'_>,
        request: Request,
        next: NextPrepareRequest<'_>,
    ) -> ServerResult<Request> {
        let request = request.data(self.collector.clone());
        next.run(ctx, request).await
    }

    async fn request(&self, ctx: &ExtensionContext<'_>, next: NextRequest<'_>) -> Response {
        let mut response = next.run(ctx).await;
        let entries = self.collector.drain_warnings();
        let arr: Vec<_> = entries
            .into_iter()
            .map(|e| serde_json::json!({"code": e.code, "message": e.message}))
            .collect();
        // Input is a hand-built array of {code: string, message: string}
        // objects; from_json cannot fail on this shape. A failure would mean
        // serde_json or async_graphql changed their contract — surface it
        // loudly instead of silently degrading to an empty array.
        let value = async_graphql::Value::from_json(serde_json::Value::Array(arr))
            .expect("from_json on hand-built warnings array cannot fail");
        response.extensions.insert("warnings".to_string(), value);
        response
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn new_collector_starts_empty() {
        let collector = WarningCollector::default();
        let warnings = collector.drain_warnings();
        assert!(warnings.is_empty());
    }

    #[test]
    fn drain_warnings_returns_entries_in_order_then_clears() {
        let collector = WarningCollector::default();
        collector.push_warning("CODE_A", "msg a".to_string());
        collector.push_warning("CODE_B", "msg b".to_string());

        let first_drain = collector.drain_warnings();
        assert_eq!(
            first_drain,
            vec![
                WarningEntry {
                    code: "CODE_A",
                    message: "msg a".to_string(),
                },
                WarningEntry {
                    code: "CODE_B",
                    message: "msg b".to_string(),
                },
            ]
        );
        assert!(collector.drain_warnings().is_empty());
    }

    #[test]
    fn two_instances_do_not_share_state() {
        let collector_a = WarningCollector::default();
        let collector_b = WarningCollector::default();
        collector_a.push_warning("ONLY_IN_A", "pushed to a".to_string());

        let b_warnings = collector_b.drain_warnings();
        assert!(
            b_warnings.is_empty(),
            "collector_b should not see collector_a's warnings"
        );

        let a_warnings = collector_a.drain_warnings();
        assert_eq!(
            a_warnings,
            vec![WarningEntry {
                code: "ONLY_IN_A",
                message: "pushed to a".to_string(),
            }]
        );
    }
}

use ddb_core::service::DoogatService;
use ddb_core::sql_engine::SqlResult;

use crate::CREATE_APP_GUIDE;

pub(crate) fn help(topic: Option<String>) -> ddb_core::error::Result<()> {
    match topic.as_deref() {
        Some("create-app") => outln!("{CREATE_APP_GUIDE}")?,
        Some(other) => {
            return Err(ddb_core::error::DoogatError::Validation(format!(
                "unknown guide: {other}\n\nAvailable guides:\n  create-app    Data modeling, zones, title resolution, and API access"
            )));
        }
        None => {
            outln!("Available guides:")?;
            outln!("  create-app    Data modeling, zones, title resolution, and API access")?;
            outln!("")?;
            outln!("Usage: ddb help <topic>")?;
        }
    }
    Ok(())
}

pub(crate) fn query(repo: &std::path::Path, sql: &str) -> ddb_core::error::Result<()> {
    let mut svc = DoogatService::open(repo)?;
    svc.rebuild_if_stale()?;
    for result in svc.execute_batch(sql)? {
        match result {
            SqlResult::Rows { rows, .. } => {
                for row in rows {
                    outln!("{}", row.join(" | "))?;
                }
            }
            SqlResult::Affected(n) => outln!("{n} row(s) affected")?,
            SqlResult::Ok(msg) => outln!("{msg}")?,
        }
    }
    Ok(())
}

pub(crate) fn search(
    repo: &std::path::Path,
    query: &str,
    limit: usize,
    offset: usize,
) -> ddb_core::error::Result<()> {
    let svc = DoogatService::open(repo)?;
    let result = svc.search_paginated(query, limit, offset)?;
    if result.hits.is_empty() {
        outln!("no results")?;
    } else {
        let start = offset + 1;
        let end = offset + result.hits.len();
        outln!("Showing {start}-{end} of {} results", result.total_count)?;
        for r in &result.hits {
            outln!("[{}] {} ({})", r.id, r.title, r.path)?;
            outln!("  {}", r.snippet)?;
        }
    }
    Ok(())
}

pub(crate) fn get(repo: &std::path::Path, id: &str) -> ddb_core::error::Result<()> {
    let svc = DoogatService::open(repo)?;
    let content = svc.read_doogat(id)?;
    out!("{content}")?;
    Ok(())
}

pub(crate) fn scan(
    repo: &std::path::Path,
    r#type: Option<String>,
    tag: Option<String>,
) -> ddb_core::error::Result<()> {
    let svc = DoogatService::open(repo)?;
    let ids = if let Some(t) = r#type {
        svc.nosql_scan_type(&t)?
    } else if let Some(t) = tag {
        svc.nosql_scan_tag(&t)?
    } else {
        return Err(ddb_core::error::DoogatError::Validation(
            "specify --type or --tag".into(),
        ));
    };
    for id in &ids {
        outln!("{id}")?;
