    let schema = input
        .doogat_type
        .as_deref()
        .and_then(|t| schemas.iter().find(|s| s.table_name == t));

    let parsed = match schema {
        Some(schema) => self.build_typed_create(
            input,
            schema,
            &id,
            &path,
            next_counters,
            partitioned_counters,
        )?,
        None => self.build_untyped_create(input, &id, &path)?,
    };

